import type {EntryPointProps} from 'react-relay'
import {EntryPointContainer} from 'react-relay'

import type {AgentTypePageEntryPoint} from '../../pages/AgentsPages/AgentTypePage/AgentTypePage.entryPoint'
import type {AgentTypePipelinePageEntryPoint} from '../../pages/PipelinesPages/AgentsPage/AgentType/AgentTypePipelinePage.entryPoint'

export type AppAgentTypeNestedEntryPoints = {
  pipeline?: typeof AgentTypePipelinePageEntryPoint
  common?: typeof AgentTypePageEntryPoint
}

export default function AppAgentType({
  entryPoints,
}: EntryPointProps<{}, AppAgentTypeNestedEntryPoints, {}, {}>) {
  const {pipeline, common} = entryPoints

  if (pipeline) {
    return <EntryPointContainer entryPointReference={pipeline} props={{}} />
  }

  if (common) {
    return <EntryPointContainer entryPointReference={common} props={{}} />
  }

  return null
}
export type AppAgentTypeComponent = typeof AppAgentType
